import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-2]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return result

b = extract(baseline)
a = extract(after)
changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, pkg = key
    bv = b.get(key, ('N/A','N/A'))
    av = a.get(key, ('N/A','N/A'))
    if bv != av:
        changes.append((proj, pkg, bv[0], av[0], av[1]))
